import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
i,o=G['Demo pair 1 input'],G['Demo pair 1 output']
ti=G['Test input']
def f(inp):
    H=len(inp);W=len(inp[0]);out=[r[:] for r in inp]
    vert=[c for c in range(W) if len({inp[r][c] for r in range(H)})==1]
    horiz=[j for j in range(H) if len(set(inp[j]))==1]
    cnt=Counter(v for r in inp for v in r)
    bg=cnt.most_common(1)[0][0]
    ucolors={inp[u][0] for u in horiz}|{inp[v][0] for v in vert}
    sep=[k for k in ucolors if k!=bg][0]
    minor=[k for k in cnt if k not in (sep,)]
    m=min(minor,key=lambda k:cnt[k])
    cells=[(j,c) for j in range(H) for c in range(W) if inp[j][c]==m]
    if vert:
        bands=[]; prev=-1
        for u in vert+[W]: bands.append((prev+1,u-1)); prev=u-1
        anch=max(bands,key=lambda bd:(sum(1 for j,c in cells if bd[0]<=c<=bd[1]),bd))
        for bd in bands:
            a,b0=bd[0]+1,bd[1]-1
            if a<=b0:
                for j,c in cells:
                    if anch[0]<=c<=anch[1]:
                        pos=a+(c-anch[0])
                        if a<=pos<=b0: out[pos][c]=m
    elif horiz:
        bands=[]; prev=-1
        for u in horiz+[H]: bands.append((prev+1,u-1)); prev=u-1
        anch=max(bands,key=lambda bd:(sum(1 for j,c in cells if bd[0]<=j<=bd[1]),bd))
        for bd in bands:
            a,b0=bd[0]+1,bd[1]-1
            if a<=b0:
                for j,c in cells:
                    if anch[0]<=j<=anch[1]:
                        pos=a+(j-anch[0])
                        if a<=pos<=b0: out[pos][c]=m
    return out
